import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class Main {
    static double averageFromFile(String fileName) {
        int total = 0;
        int count = 0;
        try {
            for (String line : Files.readAllLines(Path.of(fileName))) {
                String[] f = line.split(",");
                if (f.length != 2) {
                    continue;
                }
                try {
                    total += Integer.parseInt(f[1].trim());
                    count++;
                } catch (NumberFormatException e) {
                    // skip a line whose mark is not a number
                }
            }
        } catch (IOException e) {
            return 0;
        }
        return count == 0 ? 0 : (double) total / count;
    }

    public static void main(String[] args) throws IOException {
        Files.write(Path.of("marks.txt"), List.of("Ravi,80", "Sita,absent", "Anu,70"));
        System.out.println(averageFromFile("marks.txt"));
        System.out.println(averageFromFile("nofile.txt"));
    }
}
